function UICultivateLevelUpFinishDialog:Awake()
    self:InitData()
    SetButtonAction(self.EventReceiver.gameObject, Bind(self, self.OnClickEventReceiverAction))
end


function UICultivateLevelUpFinishDialog:OnInitialize()
    return CoWaitDo(function()
        if self.params.openMainCamera then
            self.controller.IsCameraState = false
        end
        if not self.params.isBack and not self.CaptureImage.isCaptured then
            self.CaptureImage:Capture()
        end
        self:RefreshUI()
    end)
end


function UICultivateLevelUpFinishDialog:OnShow()
    return CoWaitDo(function()
        local levelUpType = self.levelUpType
        local isWaitAnimatePlayEnd = AnimatorConfig[levelUpType]
        self.isWaitAnimatePlayEnd = isWaitAnimatePlayEnd
        local isAutoClose = false
        local isBackDialog = false
        if isWaitAnimatePlayEnd then

            local subView = self.subViews[levelUpType]
            local config = Config[levelUpType]
            local _, luaEnvPath = SafeUnpack(config)
            local env = CfUtils.GetLuaScr(subView, luaEnvPath)

            if not isNull(env) and not isNull(env.CheckAnimatorPlayComplete) then
                CoYield(env:CheckAnimatorPlayComplete())
            end

            if self.params.autoHide then
                CoYield(0.3)
                isAutoClose = true
                isBackDialog = true
            end

            if checkNumber(self.params.UITypeId) == Constants.UITypeIds.UIFishHarvestDisPlayPopupDialog then
                if FishingUtils.IsAutoing() then
                    CoYield(0.3)
                    isAutoClose = true
                    isBackDialog = false
                else
                    self._isClose = true
                end
            elseif checkNumber(self.params.UITypeId) == Constants.UITypeIds.ClubGVGEnd then
                self._isClose = true
            end
            if not isAutoClose then
                self.isWaitAnimatePlayEnd = nil
            end
        end

        if self.params.isBack and not self.CaptureImage.isCaptured then
            self._captureCo = CoStart(function() 
                CoYield(0.1)
                self.CaptureImage:Capture()
            end)
        end
        if isAutoClose then
            if isBackDialog then
                UIModule.BackDialog()
            else
                UIModule.CloseDialog(self.controller)
            end
        end
    end)
end


function UICultivateLevelUpFinishDialog:OnFinalize()
    return CoWaitDo(function()
        -- for i, loader in pairs(self.subLoaders) do
        --     loader:Release(true)
        -- end
        -- self.subLoaders = nil
        if isNotNull(self._captureCo) then
            CoStop(self._captureCo)
            self._captureCo = nil
        end
        self.params.isBack = true

        if self.params.closeCb then
            self.params.closeCb()
        end

        Events.Broadcast(Constants.EventNames.QuitLevelUpFinishDialog, self.levelUpType)

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
    end)
end


function UICultivateLevelUpFinishDialog:InitData()
    local parameters = self.controller.Argument.parameters
    self.levelUpType = parameters.levelUpType
    --self.isChangeRating = checkBool(parameters.isChangeRating)
    self.params = parameters
end


