function UICultivateLevelUpFinishDialog:RefreshUI()
    CfUtils.SetActive(self.AnimRoot, false)
    local co = self:LoadSubViewByType(self.levelUpType)
    if co then
        CoYield(co)
    end
    CfUtils.SetActive(self.AnimRoot, true)
end


---@param levelUpType Constants.UICultivateLevelUpFinishType
function UICultivateLevelUpFinishDialog:LoadSubViewByType(levelUpType)
    local config = Config[levelUpType]
    if config == nil then return end

    local prefabId, luaEnvPath, name = SafeUnpack(config)
    self.TitleText.text = name or self:GetUnlockGoodsTitle(self.params.data.goodsId)
    if self:RefreshSubView(levelUpType, luaEnvPath) then
        return
    end

    return CoStart(function()
        local go = GameUtils.LoadBundleAsyncById(prefabId, self.AnimRoot.gameObject, false, true)
        self.subViews[levelUpType] = go
        -- self.subLoaders[levelUpType] = loader
        self:RefreshSubView(levelUpType, luaEnvPath)
    end)
end


---@param subViewType Constants.UICultivateLevelUpFinishType
---@param luaEnvPath string
---@return boolean
function UICultivateLevelUpFinishDialog:RefreshSubView(subViewType, luaEnvPath)
    if self.subViews[subViewType] then
        local gameObject = self.subViews[subViewType].gameObject
        CfUtils.SetActive(gameObject, true)
        local env = CfUtils.GetLuaScr(gameObject, luaEnvPath)
        if not isNull(env) then
            xTry(function()
                env:RefreshUI(self.params, self)
            end)
        end
        return true
    end
    return false
end


function UICultivateLevelUpFinishDialog:StopLoaderCo()
    if not isNull(self.loaderCo) then
        CoStop(self.loaderCo)
        self.loaderCo = nil
    end
end

