--- 获取解锁新道具时主标题的文字
---@param goodsType any
function UICultivateLevelUpFinishDialog:GetUnlockGoodsTitle(goodsId)
    local goodsType = GoodsUtils.GetIdType(goodsId)
    local title
    if goodsType == Constants.IDType.RestaurantRecipeGoods then
        title = localize("新食谱解锁")
    elseif goodsType == Constants.IDType.GoodsCD then
        title = localize("新专辑解锁")
    else
        title = localize("新道具解锁")
    end
    return title
end

